<?php
namespace App\Jobs;
use App\Domain\BulkImport\Enums\{MigrationBatchStatus,MigrationItemStatus};use App\Domain\Documents\Services\RegisterDocument;use App\Models\{MigrationBatch,State};use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;
class CommitMigrationBatch implements ShouldQueue{use Queueable;public int $timeout=1200;public function __construct(public int $batchId){$this->onQueue('imports');}public function handle():void{$batch=MigrationBatch::findOrFail($this->batchId);abort_unless($batch->approved_at,409);$batch->update(['status'=>MigrationBatchStatus::Importing]);$state=State::where('code','AS')->firstOrFail();$batch->items()->whereIn('status',[MigrationItemStatus::Valid,MigrationItemStatus::Warning,MigrationItemStatus::Failed])->orderBy('id')->chunkById(250,function($items)use($batch,$state){foreach($items as $item){if($item->document_id){$item->update(['status'=>MigrationItemStatus::Success]);continue;}try{$item->update(['status'=>MigrationItemStatus::Registering,'attempt_count'=>$item->attempt_count+1,'started_at'=>now()]);$payload=$item->normalized_payload;$payload['state_id']=$state->id;$document=app(RegisterDocument::class)->execute($payload,$batch->created_by);$item->update(['document_id'=>$document->id,'status'=>MigrationItemStatus::Success,'completed_at'=>now(),'errors'=>null]);}catch(\Throwable $e){$item->update(['status'=>MigrationItemStatus::Failed,'completed_at'=>now(),'errors'=>['IMPORT_FAILED: '.$e->getMessage()]]);}}});$success=$batch->items()->where('status',MigrationItemStatus::Success)->count();$failed=$batch->items()->whereIn('status',[MigrationItemStatus::Failed,MigrationItemStatus::Invalid])->count();$batch->update(['committed_items'=>$success,'failed_items'=>$failed,'status'=>$failed?MigrationBatchStatus::PartiallyCompleted:MigrationBatchStatus::Completed,'completed_at'=>now()]);}}
